import { SUPABASE_URL, SUPABASE_KEY } from './supabase';
const ENDPOINT=`${SUPABASE_URL}/functions/v1/admin-api`;
async function call(action,payload={}){const token=localStorage.getItem('anish_admin_token')||'';const r=await fetch(ENDPOINT,{method:'POST',headers:{apikey:SUPABASE_KEY,'Content-Type':'application/json',...(token?{'x-admin-token':token}:{})},body:JSON.stringify({action,token,...payload})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Request failed');return d;}
export const adminLogin=async(email,password)=>{const d=await call('login',{email,password});localStorage.setItem('anish_admin_token',d.token);localStorage.setItem('anish_admin_user',JSON.stringify(d.user));return d.user};
export const adminLogout=async()=>{try{await call('logout')}catch(_){ }localStorage.removeItem('anish_admin_token');localStorage.removeItem('anish_admin_user')};
export const adminList=t=>call('list',{table:t});export const adminCreate=(t,data)=>call('create',{table:t,data});export const adminUpdate=(t,id,data)=>call('update',{table:t,id,data});export const adminDelete=(t,id)=>call('delete',{table:t,id});export const adminVisits=()=>call('visits');export const isAdminLoggedIn=()=>Boolean(localStorage.getItem('anish_admin_token'));